// Claude's review tests for A8 (select, delete and clear scenarios; Import adds or replaces).
// agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { exportProject } from '../src/core/exportFile';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, urlPattern = `/api/${id}`): Mock {
  return {
    id,
    name: id,
    enabled: true,
    method: 'GET',
    urlPattern,
    response: { status: 200, headers: {}, body: id, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
  };
}

function project(): Project {
  return {
    id: 'p1',
    name: 'site',
    origins: [fixture.origin],
    activeScenarioId: 'b',
    scenarios: [
      { id: 'default', name: 'Default', mocks: [mock('d1'), mock('d2')] },
      { id: 'a', name: 'Alpha', mocks: [mock('a1')] },
      { id: 'b', name: 'Beta', mocks: [mock('b1')] },
      { id: 'c', name: 'Gamma', mocks: [mock('c1')] },
    ],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function openMocks(): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [project()] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  await panel.getByTestId('tab-mocks').click();
  await expect(panel.locator('.scenario-group')).toHaveCount(4);
  return { page, panel };
}

const names = async () => (await readState()).projects[0]!.scenarios.map((s) => s.name);

function group(panel: Page, name: string) {
  return panel.locator('.scenario-group').filter({ has: panel.locator('.scenario-name-badge', { hasText: name }) });
}

test('every scenario but Default has a select box', async () => {
  const { page, panel } = await openMocks();
  try {
    await expect(panel.getByTestId('scenario-select')).toHaveCount(3);
    await expect(group(panel, 'Default').getByTestId('scenario-select')).toHaveCount(0);
    await expect(panel.getByTestId('scenarios-delete-selected')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Delete selected removes only the ticked scenarios, and Undo brings them back', async () => {
  const { page, panel } = await openMocks();
  try {
    await group(panel, 'Alpha').getByTestId('scenario-select').check();
    await group(panel, 'Gamma').getByTestId('scenario-select').check();
    const btn = panel.getByTestId('scenarios-delete-selected');
    await expect(btn).toHaveText('Delete selected (2)');
    await btn.click();
    await expect.poll(names).toEqual(['Default', 'Beta']);
    expect((await readState()).projects[0]!.activeScenarioId).toBe('b');
    await expect(panel.getByTestId('scenarios-delete-selected')).toHaveCount(0);

    await expect(panel.getByTestId('undo-bar')).toBeVisible();
    await panel.getByTestId('undo').click();
    await expect.poll(async () => (await readState()).projects[0]).toEqual(project());
    await expect(panel.getByTestId('undo-bar')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('ticking a box does not open that scenario', async () => {
  const { page, panel } = await openMocks();
  try {
    await group(panel, 'Default').click();
    await expect(group(panel, 'Default')).toHaveClass(/selected/);
    await group(panel, 'Gamma').getByTestId('scenario-select').check();
    await expect(group(panel, 'Default')).toHaveClass(/selected/);
    await expect(group(panel, 'Gamma')).not.toHaveClass(/selected/);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Delete all keeps only Default, emptied, and Undo restores everything', async () => {
  const { page, panel } = await openMocks();
  try {
    await panel.getByTestId('scenarios-delete-all').click();
    await expect.poll(names).toEqual(['Default']);
    const p = (await readState()).projects[0]!;
    expect(p.scenarios[0]!.mocks).toEqual([]);
    expect(p.scenarios[0]!.sockets ?? []).toEqual([]);
    expect(p.activeScenarioId).toBe('default');
    await panel.getByTestId('undo').click();
    await expect.poll(async () => (await readState()).projects[0]).toEqual(project());
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Clear all in the toolbar does the same, and the Undo bar goes after 10 s', async () => {
  const { page, panel } = await openMocks();
  try {
    await panel.getByTestId('clear-all').click();
    await expect.poll(names).toEqual(['Default']);
    await expect(panel.getByTestId('undo-bar')).toBeVisible();
    await panel.waitForTimeout(8000);
    await expect(panel.getByTestId('undo-bar')).toBeVisible();
    await expect(panel.getByTestId('undo-bar')).toHaveCount(0, { timeout: 4000 });
    expect(await names()).toEqual(['Default']);
  } finally {
    await panel.close();
    await page.close();
  }
});

function fileProject(): Project {
  return {
    id: 'f',
    name: 'file',
    origins: ['http://elsewhere.test'],
    activeScenarioId: 'fdef',
    scenarios: [
      { id: 'fdef', name: 'Default', mocks: [mock('f1', '/api/from-file')] },
      { id: 'fb', name: 'Beta', mocks: [mock('f2')] },
      { id: 'fz', name: 'Zeta', mocks: [mock('f3')] },
    ],
  };
}

async function chooseFile(panel: Page) {
  await panel.getByTestId('import').setInputFiles({
    name: 'mocks.json',
    mimeType: 'application/json',
    buffer: Buffer.from(exportProject(fileProject())),
  });
  await expect(panel.getByTestId('import-choice')).toBeVisible();
}

test('Import asks first; Cancel changes nothing', async () => {
  const { page, panel } = await openMocks();
  try {
    await chooseFile(panel);
    // Nothing is stored before a choice.
    expect((await readState()).projects).toEqual([project()]);
    await panel.getByTestId('import-cancel').click();
    await expect(panel.getByTestId('import-choice')).toHaveCount(0);
    expect((await readState()).projects).toEqual([project()]);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Import, Add to my mocks: one project, file mocks appended, names kept apart', async () => {
  const { page, panel } = await openMocks();
  try {
    await chooseFile(panel);
    await panel.getByTestId('import-add').click();
    await expect.poll(names).toEqual(['Default', 'Alpha', 'Beta', 'Gamma', 'Beta (2)', 'Zeta']);
    const s = await readState();
    expect(s.projects).toHaveLength(1);
    expect(s.projects[0]!.id).toBe('p1');
    expect(s.projects[0]!.origins).toEqual([fixture.origin]);
    expect(s.projects[0]!.scenarios[0]!.mocks.map((m) => m.urlPattern)).toEqual(['/api/d1', '/api/d2', '/api/from-file']);
    await expect(panel.getByTestId('import-summary')).toBeVisible();
    await expect(panel.getByTestId('import-choice')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Import, Replace all: same project, the file scenarios, no old project left, and Undo', async () => {
  const { page, panel } = await openMocks();
  try {
    await chooseFile(panel);
    await panel.getByTestId('import-replace').click();
    await expect.poll(names).toEqual(['Default', 'Beta', 'Zeta']);
    const s = await readState();
    expect(s.projects).toHaveLength(1);
    expect(s.projects[0]!.id).toBe('p1');
    expect(s.projects[0]!.origins).toEqual([fixture.origin]);
    expect(s.projects[0]!.scenarios[0]!.mocks.map((m) => m.urlPattern)).toEqual(['/api/from-file']);
    await expect(panel.getByTestId('import-summary')).toBeVisible();

    // The page is now answered by the file's mock.
    await page.reload();
    expect(await page.evaluate(async () => (await fetch('/api/from-file')).text())).toBe('f1');

    await panel.getByTestId('undo').click();
    await expect.poll(async () => (await readState()).projects).toEqual([project()]);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a mock file also asks, and Replace all uses it', async () => {
  const { page, panel } = await openMocks();
  try {
    // Shaped like src/core/fixtures/mock-file-v1-store.json.
    const file = {
      totalMocksCreated: 1,
      collections: [],
      mocks: [{ id: 'm1', name: 'One', method: 'GET', url: '/api/imported', status: 200, response: '{"m":1}', delay: 0,
        active: true, dynamic: false, description: '', headers: {} }],
    };
    await panel.getByTestId('import').setInputFiles({ name: 'mocks.json', mimeType: 'application/json', buffer: Buffer.from(JSON.stringify(file)) });
    await expect(panel.getByTestId('import-choice')).toBeVisible();
    await panel.getByTestId('import-replace').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios.flatMap((sc) => sc.mocks.map((m) => m.urlPattern))).toEqual(['/api/imported']);
    expect((await readState()).projects).toHaveLength(1);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a bad file shows the error and asks nothing', async () => {
  const { page, panel } = await openMocks();
  try {
    await panel.getByTestId('import').setInputFiles({ name: 'bad.json', mimeType: 'application/json', buffer: Buffer.from('{"nope":1}') });
    await expect(panel.getByTestId('import-error')).toBeVisible();
    await expect(panel.getByTestId('import-choice')).toHaveCount(0);
    expect((await readState()).projects).toEqual([project()]);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the single Delete button also offers Undo', async () => {
  const { page, panel } = await openMocks();
  try {
    await group(panel, 'Gamma').click();
    await panel.getByTestId('scenario-delete').click();
    await expect.poll(names).toEqual(['Default', 'Alpha', 'Beta']);
    await expect(panel.getByTestId('undo-bar')).toContainText('Gamma');
    await panel.getByTestId('undo').click();
    await expect.poll(async () => (await readState()).projects[0]).toEqual(project());
  } finally {
    await panel.close();
    await page.close();
  }
});

test('only the first scenario lacks a box, even when another is called Default', async () => {
  const p = project();
  p.scenarios[1]!.name = 'Default';
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  try {
    await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
    await panel.getByTestId('tab-mocks').click();
    await expect(panel.getByTestId('scenario-select')).toHaveCount(3);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a broken wemock file says what is wrong with it', async () => {
  const { page, panel } = await openMocks();
  try {
    const file = JSON.parse(exportProject(fileProject()));
    const text = JSON.stringify(file).replace('"createdAt":0', '"createdAt":"soon"');
    expect(text).toContain('"createdAt":"soon"');
    await panel.getByTestId('import').setInputFiles({ name: 'broken.json', mimeType: 'application/json', buffer: Buffer.from(text) });
    await expect(panel.getByTestId('import-error')).toContainText('createdAt');
  } finally {
    await panel.close();
    await page.close();
  }
});
